sys_script.script:
(function () {
    var splitPct = parseFloat(current.getValue('royalty_split_pct'));

    // Validate individual split is between 0 and 100
    if (isNaN(splitPct) || splitPct < 0 || splitPct > 100) {
        gs.addErrorMessage(
            'Royalty split percentage must be between 0 and 100. Current value: ' + current.getValue('royalty_split_pct')
        );
        current.setAbortAction(true);
        return;
    }

    // Check total splits for the song (warn if not 100)
    var songSysId = current.getValue('song');
    if (songSysId) {
        var contribGr = new GlideRecord('x_2015479_wa_str_0_contributor');
        contribGr.addQuery('song', songSysId);

        // Exclude the current record on update to avoid double-counting
        var currentSysId = current.getUniqueValue();
        if (currentSysId) {
            contribGr.addQuery('sys_id', '!=', currentSysId);
        }
        contribGr.query();

        var totalSplit = splitPct;
        while (contribGr.next()) {
            totalSplit += parseFloat(contribGr.getValue('royalty_split_pct')) || 0;
        }

        if (Math.abs(totalSplit - 100) > 0.01) {
            gs.addInfoMessage(
                'Warning: Total royalty splits for this song = ' +
                    totalSplit.toFixed(2) +
                    '%. Splits should sum to 100%.'
            );
        }
    }
})();
